import sys

def greet(name="World"):
    """Returns the greeting string without a trailing newline."""
    return f"Hello, {name}"

def main():
    """
    Main function to handle command-line arguments and print the greeting.
    Prints output directly to stdout with a newline.
    """
    if len(sys.argv) > 1:
        name = sys.argv[1]
    else:
        name = "World"

    print(f"Hello, {name}!")

if __name__ == "__main__":
    main()

